      "claim": "High-F phenolic contexts (desvenlafaxine, estetrol) are also limited in transfer because they are small, polar molecules with much lower logP than the query.",
      "card_ids": ["C01", "C14", "C15"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "contradictory",
