    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C29", "C45", "C50", "C63", "C84", "C89", "C26", "C42", "C30", "C72"]
    }
  ],
  "evidence_gaps": [
    "No direct fenretinide-specific absolute oral bioavailability measurement is present in the supplied records.",
    "Zeaxanthin low-F data are from rats and may not fully transfer to humans; human dietary data show bioavailability in lipid-rich matrices.",
    "Apatinib human F range 10-20% is borderline and partly based on unpublished dog data; species and formulation differences limit transfer.",
    "High-F anilide contexts (leflunomide/teriflunomide) differ substantially in lipophilicity, size, and ionization, limiting transfer to the query.",
    "No measured solubility/dissolution or first-pass metabolism data for the query; the logP-based solubility concern is a physicochemical prior, not endpoint evidence.",
    "The leflunomide isomer low-F record (C44) is ambiguous and was not used as a primary basis for the decision."
  ],
  "decision_summary": "Level 2 adds affirmative low-F context from zeaxanthin (extremely low in rats) and apatinib (10-20% human, 9-15% dog), which are more structurally relevant to the query's lipophilic polyene and anilide scaffold than the smaller, more polar high-F anilides. Combined with the unfavorable solubility prior and absence of direct fenretinide F data, the balance supports F < 20%, so the prediction is flipped to low with low confidence."
}

